# Generated by `shiny theme new` from shiny-fire.jpg
# Base scheme: Kanagawa Wave — https://github.com/mbadolato/iTerm2-Color-Schemes (via Ghostty)
# Edit freely; `shiny theme set <name>` re-applies.
THEME_BASE="Kanagawa Wave"
GHOSTTY_THEME="Kanagawa Wave"   # built-in: ghostty +list-themes
ACCENT_PRESET=0                    # macOS accent: -1 graphite 0 red 1 orange 2 yellow 3 green 4 blue 5 purple 6 pink
WALLPAPER="wallpaper.jpg"

BG="#1F1F28"         # window background
BG_DARK="#16161D"    # frames, omnibox
SURFACE="#2A2A37"    # borders, dividers, inactive window border
SELECTION="#502D35"  # selected rows, text selection
MUTED="#54546D"      # shortcuts, scrollbar
COMMENT="#727169"    # subtext, inactive tabs
FG="#DCD7BA"         # primary text
FG_DIM="#C8C093"     # secondary text
ACCENT="#FF5D62"     # primary accent: focus border, icons, links, text highlight, icon tint
ACCENT2="#FFA066"    # secondary accent: cursor, shortcuts, search selection
